-- ==============================================================================
-- 🦅 Phoenix 凤凰计划 · 25-26 供暖期投诉量主表与10个服务中心历史归档与新数据入库【完整合集】
-- 覆盖范围:
--   1. 5.供热公司总表 (GongRe_Sheet): 156天 * 4指标 = 624条，归档 936条
--   2. 6.供热公司分中心明细表 (GongRe_branches_detail_Sheet): 10中心 * 156天 * 4指标 = 6240条，归档 9360条
-- 合计新增入库: 6,864 条新核定标准记录
-- 合计归档封存: 10,296 条原历史记录 (加 25-26_raw_ 前缀)
-- ==============================================================================

BEGIN;

-- 【第 1 部分】总表 (GongRe_Sheet) 历史数据归档封存 (936条)
UPDATE daily_basic_data
SET item = '25-26_raw_' || item,
    item_cn = '25-26_raw_' || item_cn,
    operation_time = NOW()
WHERE sheet_name = 'GongRe_Sheet'
  AND date >= '2025-11-01' AND date <= '2026-04-05'
  AND item NOT LIKE '25-26_raw_%'
  AND item IN (
    'amount_daily_service_complaints',
    'amount_daily_net_complaints',
    'sum_month_total_net_complaints',
    'sum_season_total_net_complaints',
    'amount_daily_provincial_net_complaints',
    'amount_daily_city_net_complaints'
  );

-- 【第 2 部分】分中心明细表 (GongRe_branches_detail_Sheet) 历史数据归档封存 (9360条)
UPDATE daily_basic_data
SET item = '25-26_raw_' || item,
    item_cn = '25-26_raw_' || item_cn,
    operation_time = NOW()
WHERE sheet_name = 'GongRe_branches_detail_Sheet'
  AND date >= '2025-11-01' AND date <= '2026-04-05'
  AND item NOT LIKE '25-26_raw_%'
  AND item IN (
    'amount_daily_service_complaints',
    'amount_daily_net_complaints',
    'sum_month_total_net_complaints',
    'sum_season_total_net_complaints',
    'amount_daily_provincial_net_complaints',
    'amount_daily_city_net_complaints'
  );

